import { useEffect } from "react";
import { BACKGROUND_REFRESH_EVENT } from "@/lib/background-sync";

/** Re-run `onRefresh` every time the global 10s background sync fires. */
export function useBackgroundRefreshListener(onRefresh: () => void | Promise<void>) {
  useEffect(() => {
    const handler = () => { void onRefresh(); };
    window.addEventListener(BACKGROUND_REFRESH_EVENT, handler);
    return () => window.removeEventListener(BACKGROUND_REFRESH_EVENT, handler);
  }, [onRefresh]);
}
